17:     int nthreads = conved_height * conved_width * channels * batchsize;
18:     const int kernel_h = KERNEL_H_VALUE;
19:     const int kernel_w = KERNEL_W_VALUE;
20:     const int stride_h = STRIDE_H_VALUE;
21:     const int stride_w = STRIDE_W_VALUE;
22:     const int pad_h = PAD_H_VALUE;
23:     const int pad_w = PAD_W_VALUE;
