25: 
26: 
27: #pragma unroll
28:         for (int index = blockIdx.x * blockDim.x * 4 + threadIdx.x * 4; \
29:             index < (nthreads); \
30:             index += blockDim.x * gridDim.x * 4){
31:  
32:     // get nhwc
33:     const int c = index % channels;
34:     const int pw = (index / channels) % conved_width;
35:     const int ph = (index / channels / conved_width) % conved_height;
36:     const int n = index / channels / conved_width / conved_height;
37:  
38:     // get range of height and width
39:     int hstart = ph * stride_h - pad_h;
40:     int wstart = pw * stride_w - pad_w;
41:     int hend = min(hstart + kernel_h, height + pad_h);
42:     int wend = min(wstart + kernel_w, width + pad_w);
43:  
44: //      const int pool_size = (hend - hstart) * (wend - wstart);
45:     hstart = max(hstart, 0);
