53:     weight + c * kernel_h * kernel_w;
54:  
55:     int khstart=hend<kernel_h?kernel_h-hend:0;
56:     int kwstart=wend<kernel_w?kernel_w-wend:0;
57:  
58:     register uint8_t bottom_reg[4] = {0};
59:     register uint8_t weight_reg[4] = {0};
60:  
61: #pragma unroll
62:     for(int h = hstart; h < hend; ++h) {
63:     #pragma unroll
64:         for(int w = wstart; w < wend; ++w) {
65:             bottom_reg[w-wstart] = 
