63:  void SortedRowSwizzle(int rows, int *row_offsets, int *row_indices) {
64:    // Create our unsorted row indices.
65:    std::vector<int> swizzle_staging(rows);
66:    std::iota(swizzle_staging.begin(), swizzle_staging.end(), 0);
67:  
68:    // Argsort the row indices based on their length.
69:    std::sort(swizzle_staging.begin(), swizzle_staging.end(),
70:              [&row_offsets](int idx_a, int idx_b) {
71:                int length_a = row_offsets[idx_a + 1] - row_offsets[idx_a];
72:                int length_b = row_offsets[idx_b + 1] - row_offsets[idx_b];
73:                return length_a > length_b;
74:              });
75:  
76:    // Copy the ordered row indices to the output.
77:    std::memcpy(row_indices, swizzle_staging.data(), sizeof(int) * rows);
78:  }
